static int max(int[] a) {
  int m = a[0];
  for (int x : a) if (x > m) m = x;
  return m;
}

static int safeDivide(int a, int b) {
  try { return a / b; }
  catch (ArithmeticException e) { System.out.println("Cannot divide by zero"); return 0; }
}

class Account {
  private String owner; protected double balance;
  Account(String o, double b) { owner = o; balance = b; }
  void deposit(double a) { if (a > 0) balance += a; }
  boolean withdraw(double a) { if (a > 0 && a <= balance) { balance -= a; return true; } return false; }
  double getBalance() { return balance; }
  void addInterest() { }
}
class SavingsAccount extends Account {
  private double rate;
  SavingsAccount(String o, double b, double r) { super(o, b); rate = r; }
  @Override void addInterest() { balance += balance * rate; }
}
Account[] accs = { new Account("A", 100), new SavingsAccount("B", 100, 0.1) };
for (Account a : accs) { a.addInterest(); System.out.println(a.getBalance()); }  // 100.0 then 110.0
// the real object decides which addInterest runs (runtime polymorphism)

public class Notebook extends JFrame {
  JTextField field = new JTextField(20);
  JTextArea area = new JTextArea(8, 20);
  Notebook() {
    super("Notebook");
    JPanel top = new JPanel(); JButton save = new JButton("Save");
    top.add(field); top.add(save);
    add(top, BorderLayout.NORTH); add(new JScrollPane(area), BorderLayout.CENTER);
    save.addActionListener(e -> {
      String sql = "INSERT INTO notes (text) VALUES (?)";
      try (Connection c = DriverManager.getConnection(url, user, pass);
           PreparedStatement ps = c.prepareStatement(sql)) {
        ps.setString(1, field.getText()); ps.executeUpdate();
        area.append(field.getText() + "\n"); field.setText("");
      } catch (SQLException ex) { JOptionPane.showMessageDialog(this, ex.getMessage()); }
    });
    setSize(350, 300); setDefaultCloseOperation(EXIT_ON_CLOSE); setVisible(true);
  }
  public static void main(String[] a) { new Notebook(); }
}
